--
-- Table structure for table `camps`
--

DROP TABLE IF EXISTS `camps`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `camps` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Name of the Camp',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Address of the camp',
  `created_by` enum('admin','user') COLLATE utf8mb4_unicode_ci DEFAULT 'admin' COMMENT 'Who created the camp may be in future user can also create camps',
  `days` int DEFAULT NULL COMMENT 'How many days this camp will stay',
  `is_completed` tinyint(1) DEFAULT '0' COMMENT 'camp is completed or not 1 => completed 0 -> not completed',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `current_year` int DEFAULT '2022',
  `archived` enum('Yes','No') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'No' COMMENT 'Yes -> Deleted  || No -> Not Deleted',
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=244 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

