--
-- Table structure for table `packing_items`
--

DROP TABLE IF EXISTS `packing_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `packing_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `category_id` bigint unsigned NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Name of the packing item',
  `quantity` int NOT NULL DEFAULT '1' COMMENT 'quantity of packing item',
  `note` text COLLATE utf8mb4_unicode_ci COMMENT 'any special thing about the item',
  `year` year DEFAULT NULL COMMENT 'For which year this packing Category is created',
  `image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `by_admin` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'is added by admin',
  `camper_id` bigint unsigned DEFAULT NULL,
  `user_id` bigint unsigned DEFAULT NULL COMMENT 'id_of that user who add this item',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `link` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sentence_id` bigint NOT NULL DEFAULT '1',
  `shop_now_active` enum('0','1') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1',
  `order` int NOT NULL DEFAULT '0',
  `pre_check_for_save` enum('1','0') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=26701 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

